INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T01', '肺は自分の筋肉で動いているの？', '肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。', '肺の中に「呼吸筋」という固有の筋肉があるように説明しない。', ARRAY['K003']::text[], ARRAY['P02','P03','P037','P151','P152','P154','P155']::text[], '{}', '[{"passage_id":"P02","chapter":1,"label":"P4 4段階の見出しと説明","asset_id":"BM-CH01-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A002.png"},{"passage_id":"P03","chapter":1,"label":"P4 換気・外呼吸・酸素運搬の説明","asset_id":"BM-CH01-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A002.png"},{"passage_id":"P037","chapter":3,"label":"P12 原図表記は第2章","asset_id":"BM-CH03-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A003.png"},{"passage_id":"P151","chapter":2,"label":"P19 呼吸メカニズム","asset_id":"BM-CH02-A009","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH02-A009.png"},{"passage_id":"P152","chapter":3,"label":"P11 肺の動き","asset_id":"BM-CH03-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A001.png"},{"passage_id":"P154","chapter":3,"label":"P14 呼吸の力学","asset_id":"BM-CH03-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A005.png"},{"passage_id":"P155","chapter":3,"label":"P15 空気の流入","asset_id":"BM-CH03-A006","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A006.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T02', '横隔膜って何？', '横隔膜は胸とお腹を隔てる、ドーム状の筋肉です。息を吸うときに縮んで下がり、胸の中の空間を広げます。安静にして息を吐くときにはゆるみます。', '筋肉の名称と働きを具体的に説明する。', ARRAY['K026']::text[], ARRAY['P037','P150']::text[], '{}', '[{"passage_id":"P037","chapter":3,"label":"P12 原図表記は第2章","asset_id":"BM-CH03-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A003.png"},{"passage_id":"P150","chapter":2,"label":"P17 横隔膜","asset_id":"BM-CH02-A007","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH02-A007.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T03', '酸素がそのままATPになるの？', '酸素そのものがATPに変わるわけではありません。ATPは細胞がエネルギーをやり取りするための分子で、酸素は栄養から得たエネルギーを使ってATPをつくる過程を支えます。', '酸素とATPを同一視せず、未確認の産生量を付け足さない。', ARRAY['K006']::text[], ARRAY['P01','P04','P043','P165','P168']::text[], '{}', '[{"passage_id":"P01","chapter":1,"label":"図版2〜3 左上・右上・右中段","asset_id":"BM-CH01-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A001.png"},{"passage_id":"P04","chapter":1,"label":"P5 上部・右側・下部ATP図","asset_id":"BM-CH01-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A003.png"},{"passage_id":"P043","chapter":5,"label":"P33 ATPサイクル","asset_id":"BM-CH05-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH05-A004.png"},{"passage_id":"P165","chapter":4,"label":"P26 酸素と細胞","asset_id":"BM-CH04-A009","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A009.jpeg"},{"passage_id":"P168","chapter":5,"label":"P40 第5章まとめ","asset_id":"BM-CH05-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH05-A002.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T04', '呼吸数は少ないほどいいの？', '回数だけで良い・悪いは決めません。安静にして、いつも通りの呼吸を1分間数え、そのときの体調や状況と一緒に記録するための項目です。', '8回以下を高評価にするなどの採点をしない。', ARRAY['K011']::text[], ARRAY['P08']::text[], '{}', '[{"passage_id":"P08","chapter":1,"label":"P8 呼吸数セルフチェックと評価表","asset_id":"BM-CH01-A006","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A006.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T05', 'SpO₂の数字だけで健康か分かる？', '数字だけでは判断しません。SpO₂は酸素とヘモグロビンの結び付きの割合を推定する指標で、測定には誤差や限界があります。症状や測定条件と合わせて扱います。', '章内で異なる数値区分を正常・受診基準として出さない。', ARRAY['K029']::text[], ARRAY['P041','P158']::text[], '{}', '[{"passage_id":"P041","chapter":4,"label":"P28 SpO₂","asset_id":"BM-CH04-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A011.png"},{"passage_id":"P158","chapter":4,"label":"第4章導入 酸素物流","asset_id":"BM-CH04-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A001.jpeg"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T06', 'HRVは高いほど健康？', '高ければ必ず健康、低ければ必ず不調という意味ではありません。HRVは拍動の間隔のゆらぎで、呼吸・姿勢・活動・睡眠などの状況と一緒に見る項目です。', '健康度の一律採点や正常値の創作をしない。', ARRAY['K033']::text[], ARRAY['P047','P178','P185']::text[], '{}', '[{"passage_id":"P047","chapter":6,"label":"6-6 心拍変動","asset_id":"BM-CH06-A016","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A016.png"},{"passage_id":"P178","chapter":6,"label":"6-13 検定ポイント","asset_id":"BM-CH06-A008","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A008.png"},{"passage_id":"P185","chapter":6,"label":"6-7 呼吸と心拍","asset_id":"BM-CH06-A017","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A017.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T07', 'プラーナは酸素のこと？', 'プラーナは、ヨガで生命エネルギーを表す伝統的な考え方です。酸素やATPと同じ物質を指す言葉としては扱いません。', '伝統的な概念と生理学的な物質を区別する。', ARRAY['K014']::text[], ARRAY['P15']::text[], '{}', '[{"passage_id":"P15","chapter":17,"label":"17-3 左側 学習テーマ・重要ポイント","asset_id":"BM-CH17-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A003.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T08', '八支則の中で呼吸はどこにある？', '教材の八支則では、呼吸を意識的に扱うプラーナーヤーマは4番目です。ヤマ、ニヤマ、アーサナに続き、その後にプラティヤハーラ、ダーラナー、ディヤーナ、サマーディが並びます。', '原稿の8要素の順序に沿い、医学的な効能に結び付けない。', ARRAY['K062']::text[], ARRAY['P077','P231']::text[], '{}', '[{"passage_id":"P077","chapter":16,"label":"16-1 八支則","asset_id":"BM-CH16-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH16-A002.png"},{"passage_id":"P231","chapter":16,"label":"第16章 八支則導入","asset_id":"BM-CH16-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH16-A001.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T09', '寝ている間は誰が呼吸を調整しているの？', '眠っている間の呼吸は主に自動調整されます。教材では、延髄や橋などによる呼吸の調整を説明しています。起きているときは、意識して呼吸を変えることもできます。', '意識していないと呼吸できない、睡眠中は絶対に止まらない、とは言わない。', ARRAY['K035','K080']::text[], ARRAY['P049','P193','P207']::text[], '{}', '[{"passage_id":"P049","chapter":7,"label":"7-2 呼吸中枢","asset_id":"BM-CH07-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A011.png"},{"passage_id":"P193","chapter":7,"label":"呼吸と脳のつながり","asset_id":"BM-CH07-A010","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A010.png"},{"passage_id":"P207","chapter":8,"label":"8-2 睡眠中の呼吸","asset_id":"BM-CH08-A014","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A014.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T10', 'いびきがあると睡眠時無呼吸なの？', 'いびきだけで睡眠時無呼吸とは診断できません。教材では、呼吸が止まると言われる、強いいびきが続く、日中の強い眠気があるなどの場合に、医療機関への相談につなぐ方針です。', 'いびきから診断せず、教材の相談方針を併記する。', ARRAY['K081','K040']::text[], ARRAY['P210','P054','P199','P205']::text[], ARRAY['S004']::text[], '[{"passage_id":"P210","chapter":8,"label":"8-5 いびきとは","asset_id":"BM-CH08-A017","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A017.png"},{"passage_id":"P054","chapter":8,"label":"8-13 指導範囲と相談","asset_id":"BM-CH08-A007","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A007.png"},{"passage_id":"P199","chapter":8,"label":"8-10 朝の呼吸チェック","asset_id":"BM-CH08-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A004.png"},{"passage_id":"P205","chapter":8,"label":"第2部 呼吸カルテ統合","asset_id":"BM-CH08-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A011.png"}]'::jsonb) ON CONFLICT (test_id) DO NOTHING;